package org.apache.lucene.tests.util;

import com.carrotsearch.randomizedtesting.OracleSupport;
import java.io.File;
import java.io.PrintWriter;
import java.lang.reflect.Field;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Calendar;
import java.util.GregorianCalendar;
import java.util.List;
import java.util.Locale;
import java.util.Random;
import java.util.SimpleTimeZone;
import java.util.TimeZone;
import org.apache.lucene.index.LogMergePolicy;
import org.apache.lucene.tests.index.AlcoholicMergePolicy;

/**
 * The oracle of the time-zone rules of {@code crates/rucene-test-framework/src/jdk/time_zone.rs}
 * (generated by {@code tools/gen/TimeZoneRules.java}) and of {@code AlcoholicMergePolicy}'s
 * calendar. Writes into {@code <out>/rucene-test-framework/}:
 *
 * <ul>
 *   <li>{@code time_zone_hours.tsv}: for every ID of {@code TimeZone.getAvailableIDs()}, sorted,
 *       {@code id, count, digest}: the FNV-1a 64-bit digest of the little-endian bytes of each
 *       (instant, {@code HOUR_OF_DAY}) pair of the zone's grid, the hour read from a new {@code
 *       GregorianCalendar(tz, Locale.ROOT)} over a fresh {@code TimeZone} (no cached rule
 *       state). The grid, rebuilt by {@code tests/time_zone_oracle.rs}: the extremes of {@code
 *       long}; {@code t - 1, t, t + 1} for every instant {@code t} of the zone's {@code ZoneInfo}
 *       transition table; for a zone with a last rule, {@code e - 1, e} for every change of
 *       {@code getOffset} found by scanning each year of {@link #YEARS} day by day and bisecting;
 *       and 64 draws of {@code TestUtil.nextLong(new Random(row), 0, Long.MAX_VALUE)}, {@code row}
 *       being the zone's row number.
 *   <li>{@code alcoholic_hours.tsv}: per seed, {@code seed, id, hour, maxMergeSize}: {@code
 *       LuceneTestCase.randomTimeZone(new Random(seed))}, then the {@code HOUR_OF_DAY} of the
 *       calendar of {@code new AlcoholicMergePolicy(tz, new Random(seed))} and its {@code
 *       maxMergeSize}.
 *   <li>{@code simple_time_zone_offsets.tsv}: per synthetic {@code SimpleTimeZone} of {@link
 *       #SYNTHETIC} (rules no JDK 25 zone has: {@code DOM_MODE}, {@code DOW_LE_DOM_MODE}, and
 *       transitions that overflow {@code long} in year 292278994), {@code id}, the fields its
 *       constructor decoded ({@link #STZ_FIELDS}), {@code count, digest}: the digest of each
 *       (instant, {@code getOffset(instant)}) pair of a fresh instance, over {@code 0, 1}, the
 *       instants near {@code Long.MAX_VALUE}, {@code e - 1, e} for every offset change in the years of {@link
 *       #SYNTHETIC_YEARS} and 64 draws as above.
 * </ul>
 *
 * Needs {@code --add-opens java.base/sun.util.calendar=ALL-UNNAMED} (the transition table).
 */
public class TimeZoneOracle {
  static final long DAY = 86_400_000L;
  static final int[] YEARS = {
    2037, 2038, 2039, 2040, 2087, 2088, 2100, 2101, 2400, 2401, 9999, 10000, 100000, 1000000,
    10000000, 100000000, 292278993, 292278994
  };
  static final long[] MAX_MINUS = {
    0, 1, 999, 3_599_999, 3_600_000, 46_799_999, 46_800_000, 50_400_000, 86_399_999, 86_400_000
  };

  static final int[] SYNTHETIC_YEARS = {1970, 2026, 2038, 100000, 292278993, 292278994};
  static final String[] STZ_FIELDS = {
    "useDaylight", "rawOffset", "dstSavings", "startYear",
    "startMode", "startMonth", "startDay", "startDayOfWeek", "startTime", "startTimeMode",
    "endMode", "endMonth", "endDay", "endDayOfWeek", "endTime", "endTimeMode"
  };
  static final int HOUR = 3_600_000;
  /** Constructor arguments of {@code SimpleTimeZone(rawOffset, ID, startMonth, startDay,
   * startDayOfWeek, startTime, startTimeMode, endMonth, endDay, endDayOfWeek, endTime,
   * endTimeMode, dstSavings)}. */
  static final Object[][] SYNTHETIC = {
    // DOM_MODE, daylight time until 17 August: in year 292278994 the instants
    // within rawOffset of Long.MAX_VALUE overflow date + rawOffset.
    {14 * HOUR, "DOM_NORTH", 0, 2, 0, 0, SimpleTimeZone.WALL_TIME,
      7, 17, 0, 6 * HOUR, SimpleTimeZone.UTC_TIME, HOUR},
    // DOM_MODE, start in December: in year 292278994 the start overflows and
    // its wrapped time of day carries over to the end.
    {0, "DOM_SOUTH", 11, 1, 0, 2 * HOUR, SimpleTimeZone.WALL_TIME,
      3, 1, 0, 2 * HOUR, SimpleTimeZone.WALL_TIME, HOUR},
    // DOW_LE_DOM_MODE (Sun<=21 .. Sun<=7), standard time.
    {-5 * HOUR, "DOW_LE", 2, -21, -Calendar.SUNDAY, 2 * HOUR, SimpleTimeZone.STANDARD_TIME,
      9, -7, -Calendar.SUNDAY, 2 * HOUR, SimpleTimeZone.STANDARD_TIME, 30 * 60_000},
    // DOW_IN_MONTH_MODE, second Sunday of March to first Sunday of November.
    {-8 * HOUR, "DOW_IN_MONTH", 2, 2, Calendar.SUNDAY, 2 * HOUR, SimpleTimeZone.WALL_TIME,
      10, 1, Calendar.SUNDAY, 2 * HOUR, SimpleTimeZone.WALL_TIME, HOUR},
    // DOW_GE_DOM_MODE start, last-Sunday end, UTC times, a southern zone.
    {10 * HOUR, "DOW_GE", 9, 1, -Calendar.SUNDAY, 2 * HOUR, SimpleTimeZone.UTC_TIME,
      3, -1, Calendar.SUNDAY, 3 * HOUR, SimpleTimeZone.UTC_TIME, HOUR},
  };

  static long h;

  static void b(long v) {
    h ^= (v & 0xff);
    h *= 0x100000001b3L;
  }

  static void record(TimeZone tz, long instant) {
    Calendar c = new GregorianCalendar((TimeZone) tz.clone(), Locale.ROOT);
    c.setTimeInMillis(instant);
    int hour = c.get(Calendar.HOUR_OF_DAY);
    for (int k = 0; k < 8; k++) b(instant >>> (8 * k));
    for (int k = 0; k < 4; k++) b(hour >>> (8 * k));
  }

  static int offset(TimeZone tz, long instant) {
    return ((TimeZone) tz.clone()).getOffset(instant);
  }

  static long jan1(int year) {
    return LocalDate.of(year, 1, 1).toEpochDay() * DAY;
  }

  static List<Long> grid(TimeZone tz, int row) throws Exception {
    List<Long> g = new ArrayList<>();
    g.add(Long.MIN_VALUE);
    g.add(Long.MIN_VALUE + 1);
    g.add(-1L);
    g.add(0L);
    g.add(1L);
    for (long k : MAX_MINUS) g.add(Long.MAX_VALUE - k);
    Class<?> zoneInfo = Class.forName("sun.util.calendar.ZoneInfo");
    Field f = zoneInfo.getDeclaredField("transitions");
    f.setAccessible(true);
    long[] transitions = (long[]) f.get(tz);
    if (transitions != null) {
      for (long val : transitions) {
        long t = val >> 12;
        g.add(t - 1);
        g.add(t);
        g.add(t + 1);
      }
    }
    boolean lastRule = zoneInfo.getMethod("getLastRuleInstance").invoke(tz) != null;
    if (lastRule) {
      for (int year : YEARS) {
        long lo = jan1(year);
        long hi = year == 292278994 ? Long.MAX_VALUE : jan1(year + 1);
        for (long x = lo; x < hi; ) {
          long y = hi - x > DAY ? x + DAY : hi;
          if (offset(tz, y) != offset(tz, x)) {
            long a = x, c = y;
            int oa = offset(tz, a);
            while (c - a > 1) {
              long m = a + (c - a) / 2;
              if (offset(tz, m) == oa) a = m;
              else c = m;
            }
            g.add(c - 1);
            g.add(c);
          }
          x = y;
        }
      }
    }
    Random r = new Random(row);
    for (int i = 0; i < 64; i++) g.add(TestUtil.nextLong(r, 0, Long.MAX_VALUE));
    return g;
  }

  static SimpleTimeZone synthetic(Object[] a) {
    return new SimpleTimeZone((Integer) a[0], (String) a[1], (Integer) a[2], (Integer) a[3],
        (Integer) a[4], (Integer) a[5], (Integer) a[6], (Integer) a[7], (Integer) a[8],
        (Integer) a[9], (Integer) a[10], (Integer) a[11], (Integer) a[12]);
  }

  static void syntheticRows(PrintWriter w) throws Exception {
    for (int row = 0; row < SYNTHETIC.length; row++) {
      Object[] a = SYNTHETIC[row];
      StringBuilder line = new StringBuilder((String) a[1]);
      // The decoded fields, as the public toString() prints them.
      String text = synthetic(a).toString();
      for (String name : STZ_FIELDS) {
        String key = (name.equals("rawOffset") ? "offset" : name) + "=";
        int at = text.indexOf("," + key) + 1 + key.length();
        int end = at;
        while (text.charAt(end) != ',' && text.charAt(end) != ']') end++;
        line.append('\t').append(text, at, end);
      }
      // No instant before 1970: a last rule is only reached beyond 2037, and
      // the port does not reproduce the Julian calendar SimpleTimeZone uses
      // before the Gregorian cutover.
      List<Long> g = new ArrayList<>();
      g.add(0L);
      g.add(1L);
      for (long k : MAX_MINUS) g.add(Long.MAX_VALUE - k);
      for (int year : SYNTHETIC_YEARS) {
        long lo = jan1(year);
        long hi = year == 292278994 ? Long.MAX_VALUE : jan1(year + 1);
        for (long x = lo; x < hi; ) {
          long y = hi - x > DAY ? x + DAY : hi;
          if (synthetic(a).getOffset(y) != synthetic(a).getOffset(x)) {
            long lo2 = x, hi2 = y;
            int oa = synthetic(a).getOffset(lo2);
            while (hi2 - lo2 > 1) {
              long m = lo2 + (hi2 - lo2) / 2;
              if (synthetic(a).getOffset(m) == oa) lo2 = m;
              else hi2 = m;
            }
            g.add(hi2 - 1);
            g.add(hi2);
          }
          x = y;
        }
      }
      Random r = new Random(row);
      for (int i = 0; i < 64; i++) g.add(TestUtil.nextLong(r, 0, Long.MAX_VALUE));
      h = 0xcbf29ce484222325L;
      for (long instant : g) {
        int offset = synthetic(a).getOffset(instant);
        for (int k = 0; k < 8; k++) b(instant >>> (8 * k));
        for (int k = 0; k < 4; k++) b(offset >>> (8 * k));
      }
      w.println(line + "\t" + g.size() + "\t" + String.format("%016x", h));
    }
  }

  public static void main(String[] args) throws Exception {
    File out = new File(args[0], "rucene-test-framework");
    out.mkdirs();
    String[] ids = TimeZone.getAvailableIDs();
    Arrays.sort(ids);
    try (PrintWriter w = new PrintWriter(new File(out, "time_zone_hours.tsv"), "UTF-8")) {
      w.println("# id\tcount\tdigest of (instant, HOUR_OF_DAY) over the grid (TimeZoneOracle)");
      for (int row = 0; row < ids.length; row++) {
        TimeZone tz = TimeZone.getTimeZone(ids[row]);
        List<Long> g = grid(tz, row);
        h = 0xcbf29ce484222325L;
        for (long instant : g) record(tz, instant);
        w.println(ids[row] + "\t" + g.size() + "\t" + String.format("%016x", h));
      }
    }
    try (PrintWriter w = new PrintWriter(new File(out, "simple_time_zone_offsets.tsv"), "UTF-8")) {
      w.println("# id\t" + String.join("\t", STZ_FIELDS) + "\tcount\tdigest of (instant, getOffset) (TimeZoneOracle)");
      syntheticRows(w);
    }
    Field calendar = AlcoholicMergePolicy.class.getDeclaredField("calendar");
    calendar.setAccessible(true);
    Field maxMergeSize = LogMergePolicy.class.getDeclaredField("maxMergeSize");
    maxMergeSize.setAccessible(true);
    List<Long> seeds = new ArrayList<>();
    for (long s : OracleSupport.seeds()) seeds.add(s);
    for (long s = 0; s < 300; s++) seeds.add(s);
    try (PrintWriter w = new PrintWriter(new File(out, "alcoholic_hours.tsv"), "UTF-8")) {
      w.println("# seed\trandomTimeZone(new Random(seed))\tHOUR_OF_DAY\tmaxMergeSize (TimeZoneOracle)");
      for (long seed : seeds) {
        TimeZone tz = LuceneTestCase.randomTimeZone(new Random(seed));
        AlcoholicMergePolicy p = new AlcoholicMergePolicy(tz, new Random(seed));
        int hour = ((Calendar) calendar.get(p)).get(Calendar.HOUR_OF_DAY);
        w.println(seed + "\t" + tz.getID() + "\t" + hour + "\t" + maxMergeSize.get(p));
      }
    }
  }
}
